internal fun gb2312Level1HanziEncode(bmp: Int): Pair<Int, Int>? {
    val pos = position(GB2312_HANZI, 0, (94 * (0xD8 - 0xB0) - 5) - 1, bmp) ?: return null
    val lead = pos / 94 + 0xB0
    val trail = pos % 94 + 0xA1
    return Pair(lead, trail)
}

internal fun gb2312Level2HanziEncode(bmp: Int): Int? {
    val start = 94 * (0xD8 - 0xB0)
    val end = GB2312_HANZI.size - 1
    val pos = position(GB2312_HANZI, start, end, bmp) ?: return null
    return pos - start
}

internal fun gb2312OtherDecode(pointer: Int): Int =
