    mapWithUnsortedRanges(GB2312_OTHER_UNSORTED_OFFSETS, GB2312_OTHER_POINTERS, bmp)

internal fun gb18030RangeDecode(pointer: Int): Int =
    mapWithRanges(GB18030_RANGE_POINTERS, GB18030_RANGE_OFFSETS, pointer)

internal fun gb18030RangeEncode(bmp: Int): Int {
    if (bmp == 0xE7C7) return 7457
    return mapWithRanges(GB18030_RANGE_OFFSETS, GB18030_RANGE_POINTERS, bmp)
